// Builds src/features/editor/emoji-data.ts from emojibase-data (devDependency).
// The generated file is checked in; re-run `node scripts/gen-emoji.mjs` after
// upgrading emojibase-data. zh gives Chinese labels/tags and group names
// (messages.json), en adds English keywords for the search index.

import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const pkg = (locale, file) =>
  JSON.parse(readFileSync(join(root, "node_modules/emojibase-data", locale, file), "utf8"));

const zh = pkg("zh", "data.json");
const en = pkg("en", "data.json");
const messages = pkg("zh", "messages.json");
const enMessages = pkg("en", "messages.json");

const enByEmoji = new Map(en.map((entry) => [entry.emoji, entry]));
const enGroupName = new Map(enMessages.groups.map((g) => [g.order, g.message]));

const keywords = (entry, enEntry) =>
  [...new Set([entry.label, entry.text, ...(entry.tags ?? []), enEntry?.label, ...(enEntry?.tags ?? [])]
    .filter(Boolean).map((word) => word.toLowerCase()))].join(" ");

const out = [];
out.push("/* Generated by scripts/gen-emoji.mjs from emojibase-data (zh + en). Do not edit by hand. */");
out.push("export interface EmojiEntry { e: string; k: string; v: number; t?: 1 }");
out.push("export interface EmojiGroup { name: string; en: string; emoji: EmojiEntry[] }");
out.push("");
out.push("export const EMOJI_GROUPS: readonly EmojiGroup[] = [");

for (const group of messages.groups) {
  const members = zh.filter((entry) => entry.group === group.order && entry.order >= 0);
  if (!members.length) continue;
  out.push(`  { name: ${JSON.stringify(group.message)}, en: ${JSON.stringify(enGroupName.get(group.order) ?? group.key)}, emoji: [`);
  for (const entry of members) {
    const enEntry = enByEmoji.get(entry.emoji);
    out.push(`    { e: ${JSON.stringify(entry.emoji)}, k: ${JSON.stringify(keywords(entry, enEntry))}, v: ${entry.version} },`);
    for (const skin of entry.skins ?? []) {
      const enSkin = enByEmoji.get(skin.emoji);
      out.push(`    { e: ${JSON.stringify(skin.emoji)}, k: ${JSON.stringify(keywords(skin, enSkin))}, v: ${skin.version}, t: 1 },`);
    }
  }
  out.push("  ] },");
}

out.push("];");
out.push("");
out.push("/** Every searchable emoji in one flat list, skins included. */");
out.push("export const EMOJI_INDEX: readonly EmojiEntry[] = EMOJI_GROUPS.flatMap((group) => group.emoji);");
out.push("");

const target = join(root, "src/features/editor/emoji-data.ts");
const text = out.join("\n");
writeFileSync(target, text);
console.log(`wrote ${target}: ${text.length} bytes`);
